import {compileGrammar} from '../grammar.js?v=1.5.2';
import {readWordFields,updateWordField,createWordField,renameWordField,deleteWordField,wordFieldUsage} from '../wordfields.js?v=1.7.2';
import {namedGrammar,putGrammar,importGrammar,exportGrammar,unusedImportName} from '../library.js?v=1.5.2';
import {LEARNING_GRAMMARS,exampleForTopic} from './grammar-examples.js?v=1.2.0';
import {learningDrafts,fourVerseLines} from './grammar-tools.js?v=1.1.0';
import {TOPICS,SOURCES} from './data.js?v=1.2.0';
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export const grammarEditorHTML=()=>'<section id="dgram-editor" class="panel section-gap" aria-labelledby="dgram-title"></section>';

export function mountGrammarEditor(root,{topic,context=topic,initialExample,hearing,note,setNotes,getLibrary,setLibrary,modal,closeModal,download,onTransfer}){
 const $=s=>root.querySelector(s),prefix='dg-'+context+'-',initial=initialExample||exampleForTopic(topic);
 const get=(key,fallback='')=>note(prefix+key,fallback);
 const put=values=>setNotes(Object.fromEntries(Object.entries(values).map(([k,v])=>[prefix+k,String(v)])));
 const example=()=>LEARNING_GRAMMARS.find(e=>e.id===$('#dg-example').value)||initial;
 root.innerHTML=`${hearing?`<aside class="feedback" id="hearing-context"><p class="eyebrow">Vom Hören zum Schreiben</p><h3>${esc(hearing.title)}</h3><p>${esc(hearing.writing)}</p><p class="small">Dieser Entwurf gehört zu diesem Hörbeispiel und wird getrennt von deinen anderen Werkstatttexten gespeichert. Beim Wiederkommen findest du deinen zuletzt bearbeiteten Editorinhalt vor.</p><a href="#hoeren">Zurück zu den Hörbeispielen</a>${note(prefix+'rules',null)!==null?'<p class="small">Deine bisherigen Regeln sind wieder geöffnet. Das zugehörige Beispiel kannst du bei Bedarf erneut auswählen und laden.</p>':''}</aside>`:''}<p class="eyebrow">Mit Regeln dichten</p><h2 id="dgram-title">D-Gram-Regel-Editor für Lernverse</h2><p>Wähle ein Beispiel, verändere Wörter und Wendungen und höre dir deine Fassung beim Vorlesen an. Die Regeln verbinden die Wortfelder; eine ganze Fassung kann aus vier Versen bestehen.</p>
 <div class="grid"><section><h3>Ein Beispiel untersuchen</h3><label class="field" for="dg-example">Beispielgrammatik</label><select id="dg-example">${LEARNING_GRAMMARS.map(e=>`<option value="${e.id}" ${e.id===get('example',initial.id)?'selected':''}>${esc(e.name)}</option>`).join('')}</select><div id="dg-example-info" class="feedback"></div><div class="actions"><button id="dg-load-example">Beispiel laden</button><button id="dg-undo" ${get('has-previous')==='ja'?'':'disabled'}>Vorherige Regeln zurückholen</button></div><p class="small">Die Auswahl allein verändert nichts. Beim Laden wird der bisherige Editorinhalt für die Wiederherstellung aufgehoben. Deine vier Versfelder bleiben erhalten. Alle Beispiele sind eigens geschriebene Übungen, keine Wartke-Originaltexte.</p></section>
 <section><h3>Eigene Grammatiken aufbewahren</h3><label class="field" for="dg-name">Name deiner Grammatik</label><input type="text" maxlength="80" id="dg-name" value="${esc(get('name',initial.name))}"><div class="actions"><button id="dg-save">Grammatik speichern</button><button id="dg-export">Aktuelle Grammatik als Datei sichern</button></div><label class="field" for="dg-library">Gespeicherte Grammatik</label><select id="dg-library"></select><div class="actions"><button id="dg-load-saved">Gespeicherte Grammatik laden</button></div><label class="file-button">Grammatikdatei laden<input type="file" id="dg-import" accept="application/json,.json"></label><p class="small">Auch unfertige Regeln bleiben gespeichert. Die Sammlung gehört zum Wartke-Journal. Dateien aus dem Clara-Lösel-Editor lassen sich ebenfalls laden; gleiche Namen erhalten einen Zusatz.</p></section></div>
 <div class="grid"><section><h3>Regeln bearbeiten</h3><label class="field" for="dg-rules">D-Gram-Regeln</label><textarea id="dg-rules" class="code-editor" maxlength="30000" rows="10" spellcheck="false">${esc(get('rules',initial.rules))}</textarea><div class="grid dg-settings"><div><label class="field" for="dg-start">Startsymbol</label><input type="text" id="dg-start" maxlength="80" value="${esc(get('start','S'))}"></div><div><label class="field" for="dg-count">Anzahl Fassungen</label><input type="number" id="dg-count" min="1" max="24" value="${esc(get('count','1'))}"></div></div><details><summary>Wie die Regeln funktionieren</summary><p><code>S -&gt; Zeile "\\n" Zeile</code> verbindet zwei Zeilen mit einem Zeilenumbruch. Namen verweisen auf Regeln oder Wortfelder; wörtlicher Text steht in Anführungszeichen. <code>|</code> trennt Alternativen. Eine Zeile mit <code>#</code> beginnt einen Kommentar.</p><p class="small">Bei jeder Verwendung eines Wortfelds wird neu gewählt. Für zusammengehörige Fakten oder Reimpaare verwende passende eigene Felder oder vollständige zusammengehörige Formulierungen. Der Editor prüft die Syntax; fachliche Richtigkeit, Reim und Metrum prüfst du selbst.</p></details></section>
 <section><h3>Wortfelder ohne Regelsyntax bearbeiten</h3><p class="small">Ein Eintrag kann ein Wort, eine Wendung oder eine ganze Aussage sein. Änderungen erscheinen zugleich in der Textansicht.</p><div id="dg-fields"></div><details class="dg-create"><summary>Ein eigenes Wortfeld anlegen</summary><form id="dg-create-form"><label class="field" for="dg-field-name">Name des neuen Wortfelds</label><input type="text" id="dg-field-name" maxlength="60" placeholder="Zum Beispiel Messwerte"><label class="field" for="dg-field-values">Wörter oder Wendungen · ein Eintrag pro Zeile</label><textarea id="dg-field-values" rows="3" maxlength="20000"></textarea><button type="submit">Wortfeld anlegen</button><p class="small">Leerzeichen im Namen werden Unterstriche. Verwende den Namen anschliessend in einer Regel, damit das neue Feld in der Ausgabe vorkommt.</p></form></details><details><summary>Wortfelder als Text bearbeiten</summary><label class="field" for="dg-words">D-Gram-Wortfelder</label><textarea id="dg-words" class="code-editor" rows="8" maxlength="30000" spellcheck="false">${esc(get('words',initial.words))}</textarea></details></section></div>
 <div class="actions"><button class="primary" id="dg-generate">Lernverse erzeugen</button><button id="dg-check">Regeln prüfen</button></div><p id="dg-status" class="feedback" role="status" aria-live="polite">Verändere zunächst einen Eintrag und erzeuge dann eine Fassung.</p><div id="dg-output"></div><details><summary>Ableitung ansehen</summary><pre id="dg-trace" class="dg-trace">Die Ableitung erscheint nach dem Erzeugen.</pre></details>`;
 const status=(text,error=false)=>{const el=$('#dg-status');el.textContent=text;el.classList.toggle('error',error);};
 const entry=()=>namedGrammar({name:$('#dg-name').value||'Meine Lernverse',rules:$('#dg-rules').value,words:$('#dg-words').value,start:$('#dg-start').value.trim(),count:Number($('#dg-count').value)});
 const persist=()=>put({name:$('#dg-name').value,rules:$('#dg-rules').value,words:$('#dg-words').value,start:$('#dg-start').value,count:$('#dg-count').value});
 const invalidate=()=>{put({dirty:'ja'});$('#dg-output').querySelectorAll('[data-dg-transfer]').forEach(b=>b.disabled=true);if($('#dg-output').textContent)status('Die Regeln oder Wortfelder wurden verändert. Erzeuge neue Fassungen, bevor du eine übernimmst.');};
 const snapshot=()=>{persist();put({'previous-rules':$('#dg-rules').value,'previous-words':$('#dg-words').value,'previous-start':$('#dg-start').value,'previous-count':$('#dg-count').value,'previous-name':$('#dg-name').value,'previous-target':get('target',topic),'has-previous':'ja'});$('#dg-undo').disabled=false;};
 const apply=next=>{for(const key of ['rules','words','start','count','name'])if(next[key]!==undefined)$('#dg-'+key).value=next[key];persist();invalidate();drawFields();};
 const confirmLoad=(next,done)=>{modal('<h2>Regeln in den Editor laden?</h2><p>Die aktuellen Regeln und Wortfelder werden ersetzt und können über «Vorherige Regeln zurückholen» wiederhergestellt werden. Deine vier Versfelder bleiben erhalten.</p><div class="actions"><button id="dg-cancel">Abbrechen</button><button class="primary" id="dg-confirm-load">In den Editor laden</button></div>');document.querySelector('#dg-cancel').onclick=closeModal;document.querySelector('#dg-confirm-load').onclick=()=>{snapshot();apply(next);closeModal();done?.();status('Grammatik geladen. Erzeuge eine Fassung und prüfe den fachlichen Kern.');};};
 const info=()=>{const e=example(),s=SOURCES.find(s=>s.id===e.source);$('#dg-example-info').innerHTML=`<strong>${esc(e.form)}</strong><p>${esc(e.task)}</p><p class="small">${esc(e.hint)}</p>${s?`<a class="source-link" target="_blank" rel="noopener noreferrer" href="${esc(s.url)}">${esc(s.title)}</a>`:''}`;};
 $('#dg-example').onchange=()=>{put({example:$('#dg-example').value});info();};info();
 $('#dg-load-example').onclick=()=>{const e=example();confirmLoad({...e,start:'S',count:1},()=>put({target:e.topic}));};
 $('#dg-undo').onclick=()=>{const target=get('previous-target',topic),previous=Object.fromEntries(['rules','words','start','count','name'].map(k=>[k,get('previous-'+k)]));snapshot();apply(previous);put({target});status('Vorheriger Editorinhalt wiederhergestellt. Erzeuge die Fassungen neu.');};
 for(const key of ['rules','words','start','count','name'])$('#dg-'+key).addEventListener('input',()=>{persist();if(key!=='name')invalidate();if(key==='words')drawFields();});

 function drawFields(){
  let fields;try{fields=readWordFields($('#dg-words').value);}catch(error){$('#dg-fields').textContent=error.message;return;}
  $('#dg-fields').innerHTML=fields.map(field=>field.values?`<fieldset class="dg-wordfield" data-dg-field="${field.index}"><legend>${esc(field.name)}</legend><div class="actions"><button type="button" data-dg-rename aria-label="Wortfeld ${esc(field.name)} umbenennen">Umbenennen</button><button type="button" data-dg-delete aria-label="Wortfeld ${esc(field.name)} löschen">Wortfeld löschen</button></div>${field.values.map((value,i)=>`<div class="dg-word-row"><div><label class="field" for="dg-word-${field.index}-${i}">${esc(field.name)} · Eintrag ${i+1}</label><textarea id="dg-word-${field.index}-${i}" rows="2" maxlength="30000" data-dg-word="${i}">${esc(value)}</textarea></div><button type="button" data-dg-remove="${i}" aria-label="Eintrag ${i+1} aus ${esc(field.name)} entfernen" ${field.values.length===1?'disabled':''}>Entfernen</button></div>`).join('')}<button type="button" data-dg-add aria-label="Eintrag zu ${esc(field.name)} hinzufügen">Eintrag hinzufügen</button></fieldset>`:`<p class="feedback">${esc(field.name)}: ${esc(field.error)} Bearbeite diese Zeile in der Textansicht der Wortfelder.</p>`).join('')||'<p>Noch keine Wortfelder. Lege eines an oder lade ein Beispiel.</p>';
  $('#dg-fields').querySelectorAll('[data-dg-field]').forEach(group=>{
   const index=Number(group.dataset.dgField);
   const current=()=>readWordFields($('#dg-words').value).find(f=>f.index===index);
   const write=values=>{const words=updateWordField($('#dg-words').value,index,values);if(words.length+$('#dg-rules').value.length>30000)throw Error('Regeln und Wortfelder dürfen zusammen höchstens 30.000 Zeichen enthalten.');$('#dg-words').value=words;persist();invalidate();};
   group.querySelectorAll('[data-dg-word]').forEach(input=>input.oninput=()=>{try{const values=[...current().values];values[Number(input.dataset.dgWord)]=input.value;write(values);}catch(error){invalidate();status(error.message,true);}});
   group.querySelector('[data-dg-add]').onclick=()=>{try{snapshot();write([...current().values,'']);drawFields();const inputs=$('#dg-fields').querySelectorAll(`[data-dg-field="${index}"] [data-dg-word]`);inputs[inputs.length-1]?.focus();}catch(error){status(error.message,true);}};
   group.querySelectorAll('[data-dg-remove]').forEach(button=>button.onclick=()=>{try{snapshot();write(current().values.filter((_,i)=>i!==Number(button.dataset.dgRemove)));drawFields();}catch(error){status(error.message,true);}});
   group.querySelector('[data-dg-rename]').onclick=()=>{modal(`<h2>Wortfeld umbenennen</h2><p>Die Verweise in den Regeln und das Startsymbol werden automatisch angepasst.</p><form id="dg-rename-form"><label class="field" for="dg-new-name">Neuer Name</label><input type="text" maxlength="60" id="dg-new-name" value="${esc(current().name)}"><p id="dg-modal-error" role="status"></p><button type="submit">Name speichern</button></form>`);document.querySelector('#dg-rename-form').onsubmit=event=>{event.preventDefault();try{const next=renameWordField($('#dg-rules').value,$('#dg-words').value,$('#dg-start').value,index,document.querySelector('#dg-new-name').value);snapshot();apply({rules:next.rules,words:next.words,start:next.start});closeModal();status('Wortfeld umbenannt; seine Verweise sind angepasst.');}catch(error){document.querySelector('#dg-modal-error').textContent=error.message;}};};
   group.querySelector('[data-dg-delete]').onclick=()=>{const usage=wordFieldUsage($('#dg-rules').value,$('#dg-words').value,$('#dg-start').value,index),others=readWordFields($('#dg-words').value).filter(f=>f.values&&f.name!==usage.name);modal(`<h2>Wortfeld «${esc(usage.name)}» löschen?</h2><p>${usage.used?'Das Feld wird noch verwendet. Wähle ein anderes Wortfeld als Ersatz für seine Verweise.':'Die Einträge werden aus dem Editor entfernt.'} Die Änderung lässt sich über «Vorherige Regeln zurückholen» rückgängig machen.</p>${usage.used?`<label class="field" for="dg-replacement">Verweise ersetzen durch</label><select id="dg-replacement"><option value="">Wortfeld wählen</option>${others.map(f=>`<option>${esc(f.name)}</option>`).join('')}</select>`:''}<p id="dg-modal-error" role="status"></p><div class="actions"><button id="dg-cancel">Abbrechen</button><button id="dg-confirm-delete" ${usage.used&&!others.length?'disabled':''}>Wortfeld löschen</button></div>`);document.querySelector('#dg-cancel').onclick=closeModal;document.querySelector('#dg-confirm-delete').onclick=()=>{try{const next=deleteWordField($('#dg-rules').value,$('#dg-words').value,$('#dg-start').value,index,document.querySelector('#dg-replacement')?.value||'');snapshot();apply(next);closeModal();status('Wortfeld gelöscht. Prüfe bei ersetzten Verweisen auch den Sinn.');}catch(error){document.querySelector('#dg-modal-error').textContent=error.message;}};};
  });
 }
 $('#dg-create-form').onsubmit=event=>{event.preventDefault();try{const next=createWordField($('#dg-rules').value,$('#dg-words').value,$('#dg-field-name').value,$('#dg-field-values').value.split(/\r?\n/).map(v=>v.trim()).filter(Boolean));snapshot();apply({words:next.words});$('#dg-field-name').value='';$('#dg-field-values').value='';status(`Wortfeld «${next.name}» angelegt. Verwende seinen Namen in einer Regel.`);}catch(error){status(error.message,true);}};
 drawFields();

 const refreshLibrary=()=>{const selected=get('selected'),entries=getLibrary();$('#dg-library').innerHTML='<option value="">Gespeicherte Grammatik wählen</option>'+entries.map(e=>`<option ${e.name===selected?'selected':''}>${esc(e.name)}</option>`).join('');$('#dg-load-saved').disabled=!entries.some(e=>e.name===selected);};
 $('#dg-library').onchange=()=>{put({selected:$('#dg-library').value});refreshLibrary();};
 $('#dg-load-saved').onclick=()=>{const selected=getLibrary().find(e=>e.name===$('#dg-library').value);if(selected)confirmLoad(selected,()=>put({target:topic}));};
 $('#dg-save').onclick=()=>{try{persist();const next=entry(),save=replace=>{setLibrary(putGrammar(getLibrary(),next,replace));put({selected:next.name});refreshLibrary();status(`«${next.name}» gespeichert.`);};if(getLibrary().some(e=>e.name.toLocaleLowerCase('de')===next.name.toLocaleLowerCase('de'))){modal('<h2>Gespeicherte Grammatik ersetzen?</h2><p>Unter diesem Namen ist bereits eine Grammatik vorhanden. Du kannst sie durch den aktuellen Editorinhalt ersetzen oder den Dialog schliessen und einen anderen Namen vergeben.</p><button id="dg-replace-saved">Grammatik ersetzen</button>');document.querySelector('#dg-replace-saved').onclick=()=>{try{save(true);closeModal();}catch(error){status(error.message,true);closeModal();}};}else save(false);}catch(error){status(error.message,true);}};
 $('#dg-export').onclick=()=>{try{download('wartke-grammatik.json',exportGrammar(entry()),'application/json');status('Aktuelle Grammatik als Datei gesichert.');}catch(error){status(error.message,true);}};
 $('#dg-import').onchange=async event=>{try{const file=event.target.files[0];if(!file)return;if(file.size>200000)throw Error('Die Grammatikdatei darf höchstens 200 KB gross sein.');const next=importGrammar(await file.text());next.name=unusedImportName(getLibrary(),next.name);setLibrary(putGrammar(getLibrary(),next));put({selected:next.name});refreshLibrary();status(`«${next.name}» zur Sammlung hinzugefügt. Wähle «Gespeicherte Grammatik laden», um sie zu bearbeiten.`);}catch(error){status(error.message,true);}finally{event.target.value='';}};
 refreshLibrary();
 let drafts=[];
 try{const parsed=JSON.parse(get('output','[]'));if(Array.isArray(parsed)&&parsed.length<=24&&parsed.every(x=>typeof x==='string'))drafts=parsed;}catch{}
 function drawOutput(){
  $('#dg-output').innerHTML=drafts.length?`<label class="field" for="dg-target">Fach für die Übernahme</label><select id="dg-target">${[...TOPICS.map(t=>[t.id,t.subject]),['eigen','Eigenes Thema']].map(([id,label])=>`<option value="${id}" ${id===get('target',topic)?'selected':''}>${esc(label)}</option>`).join('')}</select><p class="small">Die Regeln erzeugen Textmöglichkeiten. Prüfe Inhalt und Form vor dem Übernehmen. Bei geänderten Regeln bleibt die alte Ausgabe als Vergleich erhalten, bis du neu erzeugst.</p><div class="grid">${drafts.map((draft,i)=>{let valid=true;try{fourVerseLines(draft);}catch{valid=false;}return `<article class="panel dg-draft"><h3>Fassung ${i+1}</h3><div class="poem-preview">${esc(draft)}</div><div class="actions"><button data-dg-transfer="${i}" ${!valid||get('dirty')==='ja'?'disabled':''}>Fassung ${i+1} in die vier Verse übernehmen</button></div>${!valid?'<p class="small">Diese Fassung hat nicht genau vier ausgefüllte Verszeilen. Passe die Regeln an oder übertrage einzelne Stellen von Hand.</p>':''}</article>`;}).join('')}</div>`:'';
  if($('#dg-target'))$('#dg-target').onchange=()=>put({target:$('#dg-target').value});
  $('#dg-output').querySelectorAll('[data-dg-transfer]').forEach(button=>button.onclick=()=>{try{const lines=fourVerseLines(drafts[Number(button.dataset.dgTransfer)]),target=$('#dg-target').value,label=target===topic&&hearing?hearing.title:(TOPICS.find(t=>t.id===target)?.subject||'Eigenes Thema');modal(`<h2>Vier Verse übernehmen?</h2><p>Die vier aktuellen Versfelder unter «${esc(label)}» werden ersetzt. Die Ausgangsaussagen und ihre Quelle bleiben erhalten; gleiche sie mit den neuen Versen ab. Die manuelle fachliche Prüfung wird zurückgesetzt.</p><div class="actions"><button id="dg-cancel">Abbrechen</button><button class="primary" id="dg-confirm-transfer">Vier Verse übernehmen</button></div>`);document.querySelector('#dg-cancel').onclick=closeModal;document.querySelector('#dg-confirm-transfer').onclick=()=>{closeModal();onTransfer(target,lines);};}catch(error){status(error.message,true);}});
 }
 $('#dg-check').onclick=()=>{try{persist();const e=entry(),grammar=compileGrammar(e.rules,e.words,e.start);status('Die Regeln sind ausführbar. '+(grammar.warnings.join(' ')||'Alle Bausteine werden vom Startsymbol erreicht.')+' Inhalt und Klang sind damit noch nicht geprüft.');}catch(error){status(error.message,true);}};
 $('#dg-generate').onclick=()=>{try{persist();const result=learningDrafts(entry());drafts=result.drafts;put({output:JSON.stringify(drafts),dirty:'nein'});$('#dg-trace').textContent=result.trace;drawOutput();status(`${drafts.length} ${drafts.length===1?'Fassung erzeugt':'Fassungen erzeugt'}. Lies laut und prüfe die fachlichen Aussagen. ${result.warnings.join(' ')}`);}catch(error){invalidate();status(error.message,true);}};
 drawOutput();
 if(drafts.length&&get('dirty')==='ja')status('Die angezeigte Ausgabe stammt aus einem früheren Regelstand. Erzeuge neue Fassungen.');
}
